SELECT p.gender, p.age, COUNT(DISTINCT a.subject_id) AS admission_count, AVG(l.value) AS avg_hs_tn_t, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY l.value) - PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY l.value) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'F' AND p.age BETWEEN 55 AND 65 AND l.itemid = 8718088 AND l.value > 0.01 GROUP BY p.gender, p.age;